1	import { Navigate, Outlet } from "react-router-dom";
2	import { useAuth } from "@/contexts/AuthContext";
3	import { toast } from "sonner";
4	import { useEffect, useRef } from "react";
5	
6	export function AdminRoute() {
7	  const { user, profile, loading } = useAuth();
8	  const toastShownRef = useRef(false);
9	
10	  const isAdmin =
11	    profile?.role === "admin" || profile?.role === "super_admin";
12	
13	  useEffect(() => {
14	    // Only show the toast once when we know auth is resolved and user is not an admin
15	    if (!loading && user && profile && !isAdmin && !toastShownRef.current) {
16	      toastShownRef.current = true;
17	      toast.error("Access denied. Admin privileges required.");
18	    }
19	  }, [loading, user, profile, isAdmin]);
20	
21	  if (loading) {
22	    return (
23	      <div className="flex min-h-screen items-center justify-center bg-background">
24	        <div className="h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent" />
25	      </div>
26	    );
27	  }
28	
29	  if (!user) {
30	    return <Navigate to="/login" replace />;
31	  }
32	
33	  if (!isAdmin) {
34	    return <Navigate to="/dashboard" replace />;
35	  }
36	
37	  return <Outlet />;
38	}
