16	
17	interface UrlInputProps {
18	  showPageType?: boolean;
19	  buttonText?: string;
20	  size?: "default" | "lg";
21	  className?: string;
22	  onSubmit?: (url: string, pageType: PageType) => void;
23	}
24	
25	export function UrlInput({
26	  showPageType = false,
27	  buttonText = "Analyze Now",
28	  size = "default",
29	  className,
30	  onSubmit,
31	}: UrlInputProps) {
32	  const [url, setUrl] = useState("");
33	  const [pageType, setPageType] = useState<PageType>("landing");
34	  const navigate = useNavigate();
35	
36	  const handleSubmit = (e: React.FormEvent) => {
37	    e.preventDefault();
38	    const trimmed = url.trim();
39	    if (!trimmed) return;
40	
41	    // Normalize: add https:// if missing
42	    const normalized = /^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`;
43	
44	    if (onSubmit) {
45	      onSubmit(normalized, pageType);
46	    } else {
47	      navigate(`/scan?url=${encodeURIComponent(normalized)}&type=${pageType}`);
48	    }
49	  };
50	
51	  const isLarge = size === "lg";
52	
53	  return (
54	    <form onSubmit={handleSubmit} className={cn("w-full", className)}>
55	      <div className={cn("flex gap-2", isLarge ? "flex-col sm:flex-row" : "flex-row")}>
56	        <div className="relative flex-1">
57	          <Input
58	            type="url"
59	            placeholder="https://your-website.com/landing-page"
60	            value={url}
61	            onChange={(e) => setUrl(e.target.value)}
62	            className={cn(
63	              "border-border/50 bg-white pr-4 pl-4 text-foreground placeholder:text-muted-foreground focus-visible:ring-primary/20 focus-visible:border-primary",
64	              isLarge ? "h-14 text-base rounded-xl" : "h-10 text-sm rounded-lg"
65	            )}
66	          />
67	        </div>
68	        {showPageType && (
69	          <Select value={pageType} onValueChange={(v) => setPageType(v as PageType)}>
70	            <SelectTrigger
71	              className={cn(
72	                "w-40 border-border/50 bg-white",
73	                isLarge ? "h-14 rounded-xl" : "h-10 rounded-lg"
74	              )}
75	            >
76	              <SelectValue placeholder="Page type" />
77	            </SelectTrigger>
78	            <SelectContent>
79	              {PAGE_TYPES.map((type) => (
80	                <SelectItem key={type.value} value={type.value}>
81	                  {type.label}
82	                </SelectItem>
83	              ))}
84	            </SelectContent>
85	          </Select>
86	        )}
87	        <Button
88	          type="submit"
89	          className={cn(
90	            "shrink-0 font-semibold",
91	            isLarge
92	              ? "h-14 px-8 text-base rounded-xl"
93	              : "h-10 px-5 text-sm rounded-lg"
94	          )}
95	        >
96	          <ScanLine className={cn("mr-2", isLarge ? "h-5 w-5" : "h-4 w-4")} />
97	          {buttonText}
98	        </Button>
99	      </div>
100	    </form>
101	  );
102	}
